<script lang="ts">import type {Chip as ChipType} from '../generated/Chip';import {toneColor} from '../charts';let {chip}:{chip:ChipType}=$props();</script><span class="chip" style:color={toneColor(chip.tone)}><span class="icon">{chip.icon==='moon'?'☾':chip.icon==='flame'?'♨':chip.icon==='hrv'?'〰':chip.icon==='clock'?'◷':'◆'}</span>{#if chip.text && chip.text!=='ms'}<span class="muted">{chip.text}</span>{/if}{#if chip.value}<b class="n">{chip.value}</b>{/if}{#if chip.text==='ms'}<span class="muted">ms</span>{/if}</span>